    light += uFogColor * density * uFogB.z;

    // \u5149\u6E90\u7729\u5149\uFF1A\u4EAE\u6838 + \u5927\u534A\u5F84\u67D4\u5149 + \u6A2A\u5411\u62C9\u4E1D\u3002
